#include "mc_spi_protocol.h"
#include <string.h>
uint16_t MC_Spi_Crc16(const uint8_t *data, uint32_t length) { uint16_t crc = 0xFFFFu; for (uint32_t i=0;i<length;i++){ crc ^= data[i]; for (uint8_t b=0;b<8;b++){ crc = (crc & 1u) ? (uint16_t)((crc >> 1) ^ 0xA001u) : (uint16_t)(crc >> 1); }} return crc; }
MC_Status_t MC_Spi_EncodeFrame(uint8_t msg_type, uint16_t seq, const void *payload, uint16_t payload_len, uint8_t *frame, uint16_t cap, uint16_t *frame_len) { if (!frame || !frame_len || payload_len > MC_SPI_MAX_PAYLOAD) return MC_ERR_INVALID_ARG; uint16_t need = (uint16_t)(sizeof(MC_SpiFrameHeader_t) + payload_len + sizeof(MC_SpiFrameFooter_t)); if (cap < need) return MC_ERR_RANGE; MC_SpiFrameHeader_t h = {MC_SPI_SYNC_WORD, MC_SPI_PROTOCOL_VERSION, msg_type, payload_len, seq, 0}; h.header_crc = MC_Spi_Crc16((const uint8_t*)&h, sizeof(h)-sizeof(h.header_crc)); memcpy(frame, &h, sizeof(h)); if (payload_len && payload) memcpy(frame + sizeof(h), payload, payload_len); MC_SpiFrameFooter_t f = { MC_Spi_Crc16((const uint8_t*)payload, payload_len) }; memcpy(frame + sizeof(h) + payload_len, &f, sizeof(f)); *frame_len = need; return MC_OK; }
MC_Status_t MC_Spi_DecodeFrame(const uint8_t *frame, uint16_t frame_len, uint8_t *msg_type, uint16_t *seq, const uint8_t **payload, uint16_t *payload_len) { if (!frame || frame_len < sizeof(MC_SpiFrameHeader_t)+sizeof(MC_SpiFrameFooter_t)) return MC_ERR_INVALID_ARG; const MC_SpiFrameHeader_t *h = (const MC_SpiFrameHeader_t*)frame; if (h->sync != MC_SPI_SYNC_WORD) return MC_ERR_INVALID_STATE; if (h->version != MC_SPI_PROTOCOL_VERSION) return MC_ERR_UNSUPPORTED; uint16_t calc_h = MC_Spi_Crc16(frame, sizeof(MC_SpiFrameHeader_t)-sizeof(h->header_crc)); if (calc_h != h->header_crc) return MC_ERR_CRC; uint16_t need = (uint16_t)(sizeof(MC_SpiFrameHeader_t)+h->payload_length+sizeof(MC_SpiFrameFooter_t)); if (frame_len < need) return MC_ERR_RANGE; const uint8_t *pl = frame + sizeof(MC_SpiFrameHeader_t); const MC_SpiFrameFooter_t *f = (const MC_SpiFrameFooter_t*)(pl + h->payload_length); if (MC_Spi_Crc16(pl, h->payload_length) != f->payload_crc) return MC_ERR_CRC; if (msg_type) *msg_type = h->message_type; if (seq) *seq = h->sequence; if (payload) *payload = pl; if (payload_len) *payload_len = h->payload_length; return MC_OK; }
